const url = String(args.url || '');
if (!/^https?:\/\//i.test(url)) return { ok: false, error: '只支持 http(s) 网址' };
const r = await $tools.http_get({ url, maxChars: 300000 });
const title = (r.text.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1] || '';
const text = r.text.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
return { ok: true, status: r.status, title: title.trim().slice(0, 120), chars: text.length, head: text.slice(0, 200) };
